      "card_ids": ["C13"],
      "claim": "In humans, ibrutinib showed a protein-binding-corrected CSF/plasma ratio of 28.7%, indicating significant CNS penetration of free drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "In rats, radiolabeled FK886 (ibrutinib) achieved a brain concentration of 1412 ng eq/g at 5 min after i.v. administration, consistent with good and quick brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "In SD rats, tirabrutinib showed an unbound brain-to-plasma concentration ratio of 8.5% at Cmax after oral administration, with rapid absorption into plasma and brain.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple close analogues, including ibrutinib and tirabrutinib, demonstrate meaningful CNS access in humans and rats via CSF and brain exposure measurements. The consistent positive evidence outweighs the single negative efflux-restricted record from a more distant analogue.",
  "evidence_gaps": [
    "No direct assay on the query molecule itself; prediction relies on structural analogues.",
    "Some positive records are qualitative CSF detection without quantitative unbound brain exposure, so exact exposure margins vary across analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

